INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Baconaua', 'Baconaua', 'baconaua-2017', 'After a powerful squall, a remote fishing village wakes to find its sea mysteriously turned red and covered with thousands of floating apples. While the villagers debate whether the phenomenon is an omen, miracle, or something sinister, Divina struggles with the disappearance of her father and the harsh realities facing her family. Set in the mystic yet impoverished Verde Passage, the film explores grief, superstition, family, and survival.', '2017-01-01', 2017, 'assets/baconaua.jpg', 'https://letterboxd.com/film/baconaua/', '{"cinemalaya","indie","drama"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
