INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Requited', 'Requited', 'requited-2017', 'Matt, a man battling Parkinson’s disease and a crisis of faith, sets out to bike from Manila to Mt. Pinatubo Lake to reclaim control over his life. Along the journey, he is joined by Sandy, the person he has tried to escape but still deeply wants to be with, forcing them to confront their complicated relationship.', '2017-01-01', 2017, 'assets/requited.jpg', 'https://letterboxd.com/film/requited-2017/', '{"cinemalaya","indie","drama"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
