INSERT INTO public.films (title, original_title, slug, synopsis, release_date, release_year, poster_url, letterboxd_url, cultural_tags, language, is_classic) VALUES ('Respeto', 'Respeto', 'respeto-2017', 'Respeto follows Hendrix, an aspiring hip-hop artist struggling with crime and poverty, who forms an unlikely friendship with Doc, an aging poet haunted by his experiences during Martial Law. As they influence each other’s lives, the film explores art, identity, and survival within the underground Filipino hip-hop scene.', '2017-01-01', 2017, 'assets/respeto.jpg', 'https://letterboxd.com/film/respect-2017/', '{"cinemalaya","indie","music","drama","crime"}', 'Filipino', FALSE) ON CONFLICT (slug) DO UPDATE SET poster_url = COALESCE(EXCLUDED.poster_url, public.films.poster_url), letterboxd_url = COALESCE(EXCLUDED.letterboxd_url, public.films.letterboxd_url);
